const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const sakhaAdmin = ee.FeatureCollection("FAO/GAUL/2015/level1")
    .filter(ee.Filter.eq('ADM1_NAME', 'Sakha'));
  const geometry = sakhaAdmin.geometry();

  const startDate2015 = '2015-01-01';
  const endDate2015 = '2015-12-31';
  const startDate2021 = '2021-01-01';
  const endDate2021 = '2021-12-31';

  // 2. Data Acquisition & Check
  const burnedAreaCollection = ee.ImageCollection('MODIS/061/MCD64A1');
  const landCoverCollection = ee.ImageCollection('MODIS/006/MCD12Q1');

  // Create a forest mask from 2015 land cover data
  const lc2015 = landCoverCollection.filterDate('2015-01-01', '2015-12-31').first();
  if (!lc2015) {
      console.log("Could not get 2015 land cover data.");
      console.log("C1");
      return;
  }
  const forestMask = lc2015.select('LC_Type1')
      .remap([1, 2, 3, 4, 5], ee.List.repeat(1, 5), 0);

  const col2015 = burnedAreaCollection.filterDate(startDate2015, endDate2015);
  const col2021 = burnedAreaCollection.filterDate(startDate2021, endDate2021);

  const col2015Size = col2015.size().getInfo();
  const col2021Size = col2021.size().getInfo();

  if (col2015Size === 0 || col2021Size === 0) {
      console.log(`Image count 2015: ${col2015Size}`);
      console.log(`Image count 2021: ${col2021Size}`);
      console.log("C1");
      return;
  }

  // 3. Processing
  const burned2015 = col2015.select('BurnDate').max().gt(0).updateMask(forestMask);
  const burned2021 = col2021.select('BurnDate').max().gt(0).updateMask(forestMask);

  // The area of each pixel is constant, so we can count pixels and multiply.
  // Using reducer.sum() on the binary image is equivalent to counting pixels.
  const scale = 1000;

  const burnedPixels2015 = burned2015.reduceRegion({
      reducer: ee.Reducer.sum(),
      geometry: geometry,
      scale: scale,
      maxPixels: 1e10
  });

  const burnedPixels2021 = burned2021.reduceRegion({
      reducer: ee.Reducer.sum(),
      geometry: geometry,
      scale: scale,
      maxPixels: 1e10
  });

  // 4. Calculation
  const count2015 = ee.Number(burnedPixels2015.get('BurnDate')).getInfo();
  const count2021 = ee.Number(burnedPixels2021.get('BurnDate')).getInfo();

  if (count2015 === null || count2021 === null) {
      console.log(`2015 Burned Pixels: ${count2015}`);
      console.log(`2021 Burned Pixels: ${count2021}`);
      console.log("C3");
      return;
  }

  // Multiply by pixel area at the given scale to get area in square kilometers
  const pixelAreaSqKm = (scale * scale) / 1e6;
  const burnedArea2015 = count2015 * pixelAreaSqKm;
  const burnedArea2021 = count2021 * pixelAreaSqKm;

  // 5. Validation & Final Answer
  console.log(`Analysis Scale: ${scale}m`);
  console.log(`2015 Burned Forest Area (approx sq. km): ${burnedArea2015.toFixed(0)}`);
  console.log(`2021 Burned Forest Area (approx sq. km): ${burnedArea2021.toFixed(0)}`);

  if (burnedArea2015 > burnedArea2021) {
    console.log("A");
  } else {
    console.log("B");
  }

}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE().catch(err => {
  console.error(err);
  console.log("D");
});
